mapper.select:
SELECT reply_data.id, reply_data.feedbackId, reply_data.userId, reply_data.userName, reply_data.userAvatar, reply_data.parentId, reply_data.replyToUserId, reply_data.replyToUserName, reply_data.content, reply_data.likeCount, reply_data.liked, reply_data.official, reply_data.createdAt FROM ( SELECT c.id AS id, c.feedback_id AS feedbackId, c.user_id AS userId, COALESCE(NULLIF(u.realname, ''), u.username) AS userName, u.avatar AS userAvatar, c.parent_id AS parentId, c.reply_to_user_id AS replyToUserId, COALESCE(NULLIF(reply_user.realname, ''), reply_user.username) AS replyToUserName, c.content AS content, c.like_count AS likeCount, CASE WHEN EXISTS ( SELECT 1 FROM ts_feedback_like fl WHERE fl.user_id = #{currentUserId} AND fl.target_type = 'comment' AND fl.target_id = c.id ) THEN 1 ELSE 0 END AS liked, c.is_official AS official, c.created_at AS createdAt, ROW_NUMBER() OVER ( PARTITION BY c.parent_id ORDER BY c.created_at ASC, c.id ASC ) AS replyRowNumber FROM ts_feedback_comment c LEFT JOIN sys_user u ON u.id = c.user_id LEFT JOIN sys_user reply_user ON reply_user.id = c.reply_to_user_id WHERE c.parent_id IN
#{parentId}
AND c.is_deleted = 0 ) reply_data WHERE reply_data.replyRowNumber <= #{previewSize} ORDER BY reply_data.parentId ASC, reply_data.createdAt ASC, reply_data.id ASC
